"""What layout produces: measured content and the drawing operations.

These are the only things the page flow and the renderer need to know about.
A box carries a size and, once flowed, a position; a page is a list of drawing
operations in paint order, with the origin at the top-left corner and y growing
downwards - the renderer flips the axis for PDF.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import List, Optional

from ..document import Border, ImageRun, Link, Paragraph, Section
from ..fonts import ResolvedFont

BORDER_DASHES = {
    'dashed': (3, 2), 'dotted': (1, 2), 'dotDash': (3, 2, 1, 2),
    'dotDotDash': (3, 2, 1, 2, 1, 2), 'dashSmallGap': (2, 1),
    'dashDotStroked': (3, 2, 1, 2),
}


# ---------------------------------------------------------------------------
# drawing operations
# ---------------------------------------------------------------------------

@dataclass
class TextOp:
    x: float
    y: float                 # baseline, measured from the top of the page
    text: str
    font: str
    size: float
    color: str = '000000'
    char_space: float = 0.0
    faux_bold: bool = False
    faux_italic: bool = False
    scale: float = 100.0


@dataclass
class RectOp:
    x: float
    y: float
    w: float
    h: float
    fill: Optional[str] = None
    stroke: Optional[str] = None
    line_width: float = 0.0
    dash: Optional[tuple] = None


@dataclass
class LineOp:
    x1: float
    y1: float
    x2: float
    y2: float
    color: str = '000000'
    width: float = 0.5
    dash: Optional[tuple] = None


@dataclass
class ImageOp:
    x: float
    y: float
    w: float
    h: float
    data: bytes = b''
    fmt: str = ''
    rotation: float = 0.0
    crop: Optional[tuple] = None


@dataclass
class LinkOp:
    x: float
    y: float
    w: float
    h: float
    url: Optional[str] = None
    anchor: Optional[str] = None


@dataclass
class DestOp:
    name: str
    x: float
    y: float


@dataclass
class OutlineOp:
    title: str
    level: int
    y: float


@dataclass
class Page:
    width: float
    height: float
    number: int
    ops: List[object] = field(default_factory=list)
    section: Optional[Section] = None
    index: int = 0
    first_in_section: bool = False


# ---------------------------------------------------------------------------
# measured content
# ---------------------------------------------------------------------------

@dataclass
class Piece:
    """A drawable fragment with one font and one set of run properties."""
    text: str = ''
    font: Optional[ResolvedFont] = None
    size: float = 11.0          # drawn size (snapped to the device grid)
    measure: float = 11.0       # size Word measures advances with
    width: float = 0.0
    x: float = 0.0
    color: str = '000000'
    rise: float = 0.0
    char_space: float = 0.0
    scale: float = 100.0
    underline: Optional[str] = None
    underline_color: Optional[str] = None
    strike: bool = False
    dstrike: bool = False
    highlight: Optional[str] = None
    shade: Optional[str] = None
    link: Optional[Link] = None
    image: Optional[ImageRun] = None
    height: float = 0.0
    ascent: float = 0.0
    descent: float = 0.0
    note: Optional[tuple] = None
    border: Optional[Border] = None
    leader: bool = False        # tab leader run, kept separate when drawing


@dataclass
class Token:
    """A break opportunity: a word, a tab, an image or a forced break."""
    pieces: List[Piece] = field(default_factory=list)
    space_pieces: List[Piece] = field(default_factory=list)
    width: float = 0.0
    space_width: float = 0.0
    kind: str = 'text'           # text | tab | break | image
    break_kind: str = 'line'

    @property
    def total(self) -> float:
        return self.width + self.space_width


@dataclass
class LineBox:
    pieces: List[Piece] = field(default_factory=list)
    height: float = 0.0
    ascent: float = 0.0
    descent: float = 0.0
    natural: float = 0.0
    text_natural: float = 0.0    # height from text only, images excluded
    width: float = 0.0
    page_break: bool = False
    ends_paragraph: bool = False
    notes: List[tuple] = field(default_factory=list)


@dataclass
class ParaBox:
    para: Optional[Paragraph] = None
    lines: List[LineBox] = field(default_factory=list)
    space_before: float = 0.0
    space_after: float = 0.0
    pad_top: float = 0.0       # room a paragraph border needs
    pad_bottom: float = 0.0
    left: float = 0.0
    right: float = 0.0
    width: float = 0.0
    shading: Optional[str] = None
    borders: Optional[dict] = None
    keep_next: bool = False
    keep_lines: bool = False
    widow_control: bool = True
    page_break_before: bool = False
    outline_level: Optional[int] = None
    title: str = ''
    bookmarks: List[str] = field(default_factory=list)
    after_boxes: List[object] = field(default_factory=list)
    floats: List[tuple] = field(default_factory=list)   # (FloatingObject, boxes)
    open_top: bool = True         # this fragment starts the paragraph
    open_bottom: bool = True      # this fragment ends the paragraph

    @property
    def height(self) -> float:
        return (self.space_before + self.pad_top
                + sum(l.height for l in self.lines)
                + self.pad_bottom + self.space_after)


@dataclass
class CellBox:
    boxes: List[object] = field(default_factory=list)
    width: float = 0.0
    x: float = 0.0
    props: object = None
    grid_span: int = 1
    v_merge: Optional[str] = None
    margins: dict = field(default_factory=dict)
    borders: Optional[dict] = None
    shading: Optional[str] = None
    v_align: str = 'top'
    span_rows: int = 1

    @property
    def content_height(self) -> float:
        return sum(getattr(b, 'height', 0.0) for b in self.boxes)


@dataclass
class RowBox:
    cells: List[CellBox] = field(default_factory=list)
    height: float = 0.0
    header: bool = False
    cant_split: bool = False
    border_top: float = 0.0      # cell borders take room inside the row
    border_bottom: float = 0.0


@dataclass
class TableBox:
    rows: List[RowBox] = field(default_factory=list)
    widths: List[float] = field(default_factory=list)
    x: float = 0.0
    width: float = 0.0
    page_break_before: bool = False
    repeat_header: List[RowBox] = field(default_factory=list)

    @property
    def height(self) -> float:
        return sum(r.height for r in self.rows)
